from pathlib import Path
import json
P=Path(__file__).parent
# All diagrams are original vector drawings for this campaign.
def svg(content):
 return '<svg viewBox="0 0 900 620" fill="none" xmlns="http://www.w3.org/2000/svg">'+content+'</svg>'
def drop(x,y,s=1,cls='drip'):
 return f'<path class="{cls}" transform="translate({x} {y}) scale({s})" d="M0 -58 C-18 -30 -42 -7 -42 20 A42 42 0 0 0 42 20 C42 -7 18 -30 0 -58Z" fill="white"/><path transform="translate({x-15} {y+8}) scale({s})" d="M0 0 Q-8 18 7 28" stroke="#7135D8" stroke-width="6" stroke-linecap="round"/>'
def art(kind):
 if kind=='hero':
  return svg('<circle class="orbit" cx="450" cy="300" r="245" stroke="#7135D8" stroke-width="3" stroke-dasharray="32 22"/><circle class="ring" cx="450" cy="300" r="185" stroke="#FFC52B" stroke-width="12"/>'+drop(450,280,2.2,'main-drop')+'<path class="wave" d="M140 480 Q285 390 450 470 T770 455" stroke="#FF792E" stroke-width="22" stroke-linecap="round"/><circle cx="205" cy="165" r="26" fill="#FFC52B"/><circle cx="735" cy="395" r="15" fill="white"/>')
 if kind=='tap':
  return svg('<path d="M145 480 V290 Q145 240 200 240 H515 Q565 240 565 290 V330" stroke="#180B32" stroke-width="90" stroke-linejoin="round"/><path d="M145 475 V290 Q145 240 200 240 H515 Q565 240 565 290 V330" stroke="white" stroke-width="57" stroke-linejoin="round"/><path d="M340 240 V150" stroke="white" stroke-width="45"/><g class="valve"><rect x="245" y="115" width="190" height="36" rx="18" fill="#FFC52B"/><circle cx="340" cy="133" r="30" fill="#FF792E"/></g>'+drop(565,402,.7)+ '<circle class="check-circle" cx="735" cy="170" r="85" fill="#FFC52B"/><path class="check" d="M690 170 l32 32 58 -64" stroke="#180B32" stroke-width="18" stroke-linecap="round" stroke-linejoin="round"/>')
 if kind=='shower':
  return svg('<path d="M150 530 V150 Q150 75 225 75 H310" stroke="#7135D8" stroke-width="35"/><path d="M260 160 Q340 25 430 160Z" fill="#7135D8"/><g class="rain">'+''.join(f'<path d="M{x} 200 v180" stroke="#7135D8" stroke-width="8" stroke-dasharray="20 32" stroke-linecap="round"/>' for x in [275,310,345,380,415])+'</g><circle cx="655" cy="320" r="185" fill="#180B32"/><circle class="timer-ring" cx="655" cy="320" r="160" stroke="#FFC52B" stroke-width="18" stroke-dasharray="1005"/><path class="hand" d="M655 320 V220" stroke="white" stroke-width="15" stroke-linecap="round"/><circle cx="655" cy="320" r="17" fill="#FF792E"/>')
 if kind=='washer':
  return svg('<rect x="95" y="55" width="400" height="500" rx="44" fill="white"/><rect x="130" y="90" width="330" height="55" rx="16" fill="#180B32"/><circle cx="395" cy="117" r="13" fill="#FFC52B"/><circle cx="295" cy="337" r="155" fill="#180B32"/><g class="drum"><circle cx="295" cy="337" r="125" fill="#7135D8"/><path d="M190 340 Q240 290 295 335 T408 320 V400 Q295 475 190 400Z" fill="#FFC52B"/><path d="M210 280 l85 -25 60 72 -100 35Z" fill="white"/></g><path class="flow" d="M500 400 H600 Q650 400 650 455 V500" stroke="#FFC52B" stroke-width="20" stroke-linecap="round" stroke-dasharray="18 22"/><path d="M570 485 H790 L760 595 H600Z" fill="#FF792E"/><path d="M625 480 Q680 405 735 480" stroke="white" stroke-width="12"/>')
 if kind=='leak':
  return svg('<path d="M110 180 H450 V440 H790" stroke="#7135D8" stroke-width="90" stroke-linecap="round" stroke-linejoin="round"/><path class="flow" d="M110 180 H450 V440 H790" stroke="#FFC52B" stroke-width="12" stroke-dasharray="18 24"/>'+drop(450,300,.55)+'<g class="magnifier"><circle cx="450" cy="300" r="140" fill="#FFFFFF" stroke="#FFC52B" stroke-width="24"/><path d="M548 405 l110 110" stroke="#180B32" stroke-width="44" stroke-linecap="round"/><path d="M390 290 l40 40 82 -84" stroke="#7135D8" stroke-width="22" stroke-linecap="round" stroke-linejoin="round"/></g>')
 if kind=='plant':
  return svg('<circle cx="720" cy="145" r="85" fill="#FFC52B"/><circle cx="755" cy="115" r="76" fill="#180B32"/><path d="M340 420 H590 L550 590 H380Z" fill="#FF792E"/><path d="M465 430 V175" stroke="white" stroke-width="20" stroke-linecap="round"/><g class="leaves"><path d="M455 320 Q240 340 290 170 Q440 170 455 320" fill="#7135D8"/><path d="M475 265 Q645 245 620 100 Q465 100 475 265" fill="#FFC52B"/></g><path class="flow" d="M140 100 Q200 210 335 365" stroke="white" stroke-width="12" stroke-dasharray="18 25"/>'+drop(300,340,.42)+'<path d="M100 100 l60 -45 80 80 -55 50Z" fill="#7135D8"/>')
 if kind=='together':
  return svg('<circle class="orbit" cx="450" cy="300" r="240" stroke="#7135D8" stroke-width="4" stroke-dasharray="10 28"/>'+drop(450,280,2.0,'main-drop')+''.join(f'<g class="person"><circle cx="{x}" cy="{y}" r="30" fill="#FFC52B"/><path d="M{x-45} {y+85} Q{x} {y+5} {x+45} {y+85}" stroke="#FF792E" stroke-width="24" stroke-linecap="round"/></g>' for x,y in [(180,150),(715,150),(200,440),(700,440)]))
 return art('hero')
scenes=[
 dict(start=0,end=8,theme='dark',label='Una invitación para ti',title='CUIDEMOS EL AGUA',kind='hero',intro='El Gobierno con Sentido Humano de Tzompantepec, a través de la Coordinación de Ecología, te invita:',cards=['Campaña de Concientización sobre el Cuidado del Agua','Abierta a toda la ciudadanía']),
 dict(start=8,end=16,theme='dark',label='Cada gota cuenta',title='CIERRA LA LLAVE',kind='tap',cards=['Al lavarte los dientes.','Al rasurarte o enjabonarte.'],ribbon='Ábrela solo cuando la necesites.'),
 dict(start=16,end=23,theme='light',label='Duchas breves',title='MÁXIMO',kind='shower',big='5 MIN',cards=['Cuida el agua en cada ducha.'],ribbon='Menos tiempo, más cuidado.'),
 dict(start=23,end=32,theme='dark',label='Aprovecha mejor cada lavado',title='CARGAS COMPLETAS',kind='washer',cards=['Usa la lavadora solo con cargas completas.','Reutiliza el agua del enjuague para pisos o el sanitario.']),
 dict(start=32,end=39,theme='light',label='Revisa tu casa',title='FUGA QUE VES, FUGA QUE REPARAS',kind='leak',cards=['Detecta y repara cualquier fuga de inmediato.'],ribbon='Una pequeña fuga también desperdicia agua.'),
 dict(start=39,end=46,theme='dark',label='Tus plantas también cuentan',title='RIEGA A LA HORA CORRECTA',kind='plant',cards=['Por la noche o muy temprano.','Así evitas que el agua se evapore.']),
 dict(start=46,end=52,theme='dark',label='Cada acción cuenta',title='PEQUEÑOS CAMBIOS. GRAN DIFERENCIA.',kind='together',cards=['Cuidar el agua es compromiso de todos.']),
 dict(start=52,end=60,theme='yellow',label='¡Súmate al compromiso!',title='EL AGUA ES VIDA',kind='hero',cards=['Y nos necesita a todos.','¿Qué hábito cambiarás hoy para cuidar el agua?'])]
html=[]
for i,s in enumerate(scenes):
 intro=f'<p class="institution enter">{s["intro"]}</p>' if s.get('intro') else ''
 big=f'<div class="big enter">{s["big"]}</div>' if s.get('big') else ''
 cards=''.join(f'<div class="card enter"><span class="bullet">'+('?' if i==7 and j==1 else '✓')+f'</span><p>{c}</p></div>' for j,c in enumerate(s['cards']))
 ribbon=f'<p class="ribbon enter">{s["ribbon"]}</p>' if s.get('ribbon') else ''
 html.append(f'<section id="s{i}" class="scene {s["theme"]} scene-{i}" style="z-index:{i+1};opacity:{1 if i==0 else 0}"><div class="halo" data-layout-ignore></div><div class="scene-content">{intro}<div class="label enter">{s["label"]}</div><h1 class="enter">{s["title"]}</h1>{big}<div class="art enter" data-layout-ignore>{art(s["kind"])}</div><div class="cards">{cards}</div>{ribbon}</div></section>')
css='''@font-face{font-family:Campaign;src:url(assets/body.ttf);font-weight:400}@font-face{font-family:Campaign;src:url(assets/display.ttf);font-weight:900}*{box-sizing:border-box}body{margin:0;background:#180B32;font-family:Campaign;color:white}#root{width:1080px;height:1920px;position:relative;overflow:hidden}.scene{position:absolute;inset:0;isolation:isolate;overflow:hidden;background:#180B32}.scene-content{width:100%;height:100%;padding:90px 74px 100px;display:flex;flex-direction:column;gap:30px;justify-content:center}.scene-content{position:relative;z-index:1}.yellow .ring{stroke:#7135D8}.halo{position:absolute;inset:15% -40%;background:radial-gradient(ellipse,#7135D840,transparent 65%);z-index:0}.label{font-size:42px;font-weight:900;color:#FFC52B;letter-spacing:.01em}h1{font-size:108px;line-height:1.03;letter-spacing:-.045em;font-weight:900;margin:0;max-width:930px}.institution{font-size:43px;line-height:1.33;margin:0 0 6px;max-width:930px}.art{width:100%;height:650px;flex:1;min-height:400px;max-height:710px;display:flex;align-items:center;justify-content:center}.art svg{width:100%;height:100%;overflow:visible}.cards{display:flex;flex-direction:column;gap:18px}.card{background:#321955;border:2px solid #8864B4;border-radius:30px;padding:32px 30px;display:flex;align-items:center;gap:24px;box-shadow:0 18px 0 #0C061C35}.card p{font-size:49px;line-height:1.2;margin:0;flex:1}.bullet{background:#FFC52B;color:#180B32;border-radius:50%;width:58px;height:58px;flex:none;display:flex;align-items:center;justify-content:center;font-size:39px;font-weight:900}.ribbon{margin:0;padding:27px 32px;border-left:8px solid #FF792E;font-size:41px;line-height:1.25}.light{background:white;color:#180B32}.light .label{color:#7135D8}.light .halo{background:radial-gradient(ellipse,#FFC52B30,transparent 65%)}.light .card{background:#F3EDF9;border-color:#D9C8F2}.yellow{background:#FFC52B;color:#180B32}.yellow .label{color:#180B32}.yellow .card{background:white;border-color:white}.yellow .bullet{background:#7135D8;color:white}.yellow .halo{background:radial-gradient(ellipse,#FFFFFF70,transparent 65%)}.big{font-size:220px;line-height:.95;letter-spacing:-.07em;font-weight:900;color:#7135D8;font-variant-numeric:tabular-nums}.scene-0 h1{font-size:115px}.scene-0 .label{display:none}.scene-0 .art{min-height:380px;max-height:560px}.scene-0 .card p{font-size:43px}.scene-0 .card:last-child{background:#FFC52B;color:#180B32;border-color:#FFC52B}.scene-2 h1{font-size:110px}.scene-2 .art{max-height:590px}.scene-4 h1{font-size:100px}.scene-5 h1{font-size:101px}.scene-6 h1{font-size:103px}.scene-7 h1{font-size:140px}.scene-7 .card:last-child{background:#180B32;color:white;border-color:#180B32}.scene-7 .card:last-child p{font-size:49px;font-weight:900}.scene-7 .art{max-height:550px}'''
js='''const tl=gsap.timeline({paused:true});window.__timelines={main:tl};const scenes=SCENES;
scenes.forEach((s,i)=>{let q='#s'+i;if(i){tl.set(q,{opacity:1},s.start);tl.from(q,i===3||i===6?{y:1920,duration:.46,ease:'expo.inOut'}:{x:i%2?1080:-1080,duration:.46,ease:'expo.inOut'},s.start);tl.set('#s'+(i-1),{opacity:0},s.start+.48)}
let els=document.querySelectorAll(q+' .enter');els.forEach((el,j)=>{const at=s.start+.15+j*.12;const modes=[{y:60,opacity:0,ease:'power3.out'},{x:-65,opacity:0,ease:'expo.out'},{scale:.86,rotation:-2,opacity:0,ease:'back.out(1.15)'}];tl.from(el,{...modes[j%3],duration:.65},at)});
let base=s.start+1.5,span=s.end-base;tl.to(q+' .art',{y:-14,duration:1.6,yoyo:true,repeat:Math.max(0,Math.floor(span/1.6)-1),ease:'sine.inOut'},base);
if(document.querySelector(q+' .orbit'))tl.to(q+' .orbit',{rotation:90,svgOrigin:'450 300',duration:span,ease:'none'},base);
if(document.querySelector(q+' .ring'))tl.from(q+' .ring',{scale:.6,opacity:0,svgOrigin:'450 300',duration:1,ease:'expo.out'},s.start+.5);
if(document.querySelector(q+' .main-drop'))tl.from(q+' .main-drop',{y:150,opacity:0,duration:1,ease:'back.out(1.3)'},s.start+.45);
if(document.querySelector(q+' .drip'))tl.to(q+' .drip',{y:40,duration:.8,yoyo:true,repeat:Math.max(0,Math.floor(span/.8)-1),ease:'sine.inOut'},base);
if(document.querySelector(q+' .flow'))tl.to(q+' .flow',{strokeDashoffset:-240,duration:span,ease:'none'},base);
if(s.kind==='tap'){tl.to(q+' .valve',{rotation:25,svgOrigin:'340 133',duration:.6,ease:'back.out(2)'},s.start+2);tl.from(q+' .check-circle',{scale:0,svgOrigin:'735 170',duration:.5,ease:'back.out(1.8)'},s.start+2.4);tl.from(q+' .check',{opacity:0,duration:.25},s.start+2.6)}
if(s.kind==='shower'){tl.to(q+' .rain',{y:24,duration:.5,yoyo:true,repeat:10,ease:'none'},base);tl.to(q+' .hand',{rotation:300,svgOrigin:'655 320',duration:5,ease:'none'},base);tl.from(q+' .timer-ring',{strokeDashoffset:1005,duration:5,ease:'none'},base)}
if(s.kind==='washer')tl.to(q+' .drum',{rotation:360,svgOrigin:'295 337',duration:5.8,ease:'sine.inOut'},base);
if(s.kind==='leak')tl.from(q+' .magnifier',{x:140,y:-90,scale:.6,duration:1.2,ease:'expo.out'},s.start+.8);
if(s.kind==='plant')tl.to(q+' .leaves',{rotation:3,svgOrigin:'465 420',duration:1.1,yoyo:true,repeat:3,ease:'sine.inOut'},base);
if(s.kind==='together')tl.from(q+' .person',{scale:0,transformOrigin:'center',stagger:.2,duration:.6,ease:'back.out(1.8)'},s.start+1);
});'''.replace('SCENES',json.dumps(scenes,ensure_ascii=False))
(P/'index.html').write_text('<!doctype html><html lang="es"><head><meta charset="UTF-8"><style>'+css+'</style></head><body><div id="root" data-composition-id="main" data-start="0" data-duration="60" data-width="1080" data-height="1920">'+''.join(html)+'<audio id="effects" src="assets/efectos.wav" data-start="0" data-duration="60" data-track-index="3" data-volume="1"></audio></div><script src="assets/gsap.min.js"></script><script>'+js+'</script></body></html>')
(P/'guion.json').write_text(json.dumps(scenes,ensure_ascii=False,indent=2))
